const ICONS={'event-army.png': 'data:image/png;base64,', 'event-navigator-clean.png': 'data:image/png;base64,', 'event-elite.png': 'data:image/png;base64,', 'event-night.png': 'data:image/png;base64,', 'event-trade.svg': 'data:image/svg+xml;base64,', 'event-amber.png': 'data:image/png;base64,', 'event-advisor.png': 'data:image/png;base64,', 'event-battle.png': 'data:image/png;base64,', 'event-mobil.svg': 'data:image/svg+xml;base64,', 'event-return.png': 'data:image/png;base64,', 'event-winter.png': 'data:image/png;base64,', 'event-smoke-clean.png': 'data:image/png;base64,', 'event-fireworks.png': 'data:image/png;base64,'};
const esc=s=>String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const t=T[LANG]||T.pl;
const icon=e=>`<span class="event-icon"><img src="${ICONS[e.icon]}" alt="" aria-hidden="true"></span>`;
const label=e=>esc(e.name[LANG]||e.name.en);
function renderStatic(){
 document.querySelectorAll('[data-i18n]').forEach(el=>{const key=el.dataset.i18n;if(t[key]!==undefined)el.textContent=t[key]});
 document.getElementById('range').textContent=t.range;
 document.title=`${t.events} H0C | H0C`;
 document.getElementById('days').innerHTML=t.days.map((d,i)=>`<button class="day ${i===0?'selected':''}" data-day="${i}">${d}</button>`).join('');
 document.getElementById('mini-week').innerHTML=t.mini.map((d,i)=>`<button class="mini-day ${i===0?'selected':''}" data-day="${i}"><b>${d}</b><strong>${t.miniDates[i]}</strong></button>`).join('');
}
function renderTimeline(){const tl=document.getElementById('timeline');tl.innerHTML='';EVENTS.forEach((e,row)=>{const left=e.start/6*100,width=(e.end-e.start+1)/6*100;const r=document.createElement('div');r.className='event-row';r.style.top=`${row*50}px`;r.innerHTML=`<div class="event-bar ${e.kind}" style="left:${left}%;width:calc(${width}% - 10px)">${icon(e)}<span class="event-label">${label(e)}</span><span class="event-time">${e.time||t.allDay}</span></div>`;tl.appendChild(r)});tl.style.height=`${EVENTS.length*50+8}px`;}
function renderDaily(){const ids=['amber','return','elite','army','trade','mobil'];document.getElementById('daily-list').innerHTML=ids.map(id=>EVENTS.find(e=>e.id===id)).map(e=>`<div class="daily-item ${e.kind}">${icon(e)}<span class="daily-copy"><strong>${label(e)}</strong><small>${e.time||t.allDay}</small></span></div>`).join('');}
function renderUpcoming(){const ids=['amber','fireworks','night','smoke'];document.getElementById('upcoming-grid').innerHTML=ids.map(id=>EVENTS.find(e=>e.id===id)).map(e=>`<article class="up-item">${icon(e)}<div><h3>${label(e)}</h3><p>${t.miniDates[e.start]} – ${t.miniDates[e.end]} · ${e.time||t.allDay}</p></div></article>`).join('');}
function selectDay(i){document.querySelectorAll('.day,.mini-day').forEach(b=>b.classList.toggle('selected',Number(b.dataset.day)===i));}
document.addEventListener('DOMContentLoaded',()=>{renderStatic();renderTimeline();renderDaily();renderUpcoming();document.querySelectorAll('.day,.mini-day').forEach(b=>b.addEventListener('click',()=>selectDay(Number(b.dataset.day))));document.getElementById('today-btn').addEventListener('click',()=>selectDay(0));document.getElementById('prev-week').addEventListener('click',()=>selectDay(0));document.getElementById('next-week').addEventListener('click',()=>selectDay(5));const toggle=document.getElementById('menu-toggle'),nav=document.getElementById('site-nav');toggle.addEventListener('click',()=>{const open=nav.classList.toggle('open');toggle.setAttribute('aria-expanded',String(open));});});
